import json,re
from pathlib import Path
S=Path('/private/tmp/kuch11round/student'); D=Path(__file__).parent

def make(lesson, answers, qs):
 text=(S/(lesson+'.md')).read_text(); out=[]
 for task,code,expect in answers:
  section=re.search(r'## task: '+re.escape(task)+r' \|.*?(?=\n## task:|\Z)',text,re.S).group()
  start=re.search(r'### Заготовка\s*```python\n(.*?)```',section,re.S)
  prefix=start.group(1) if start else ''
  # Draft snippets explicitly marked in starter are replaced by complete implementations.
  if '...' in prefix: prefix=''
  out.append(dict(lesson=lesson,task=task,code=prefix+'\n'+code,expect='Q1 решить '+task+'. Q2 опора: формула и заготовка этого урока. Q3 '+expect))
 for question,choice,expect in qs: out.append(dict(question=lesson+'/'+question,choice=choice,expect='Q1 предсказать результат. Q2 читаю выражение и варианты. Q3 '+expect))
 (D/(lesson+'.input.jsonl')).write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in out))

