('own-net','rng=np.random.default_rng(0);W1=rng.normal(size=(64,32))*.1;W2=rng.normal(size=(32,10))*.1;b1=np.zeros(32);b2=np.zeros(10)\nfor _ in range(300):\n    Z1=X_train@W1+b1;H=np.maximum(0,Z1);P=softmax(H@W2+b2);D=(P-Y_train)/len(y_train);dH=D@W2.T*(Z1>0)\n    gW2=H.T@D;gb2=D.sum(axis=0);gW1=X_train.T@dH;gb1=dH.sum(axis=0)\n    W1-=.5*gW1;b1-=.5*gb1;W2-=.5*gW2;b2-=.5*gb2\nown_proba=softmax(np.maximum(0,X_test@W1+b1)@W2+b2);acc_own=round(float((own_proba.argmax(axis=1)==y_test).mean()),3)','450×10 own_proba, все градиенты на старыхW2.'),
